(function () {
  var PARAMS = ['gclid', 'gbraid', 'wbraid', 'msclkid', 'fbclid',
                'utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content'];
  try {
    var urlParams = new URLSearchParams(window.location.search);
    var found = {}, any = false;
    PARAMS.forEach(function (p) {
      var v = urlParams.get(p);
      if (v) { found[p] = v; any = true; }
    });
    if (!any) return;

    var existing = {};
    var m = document.cookie.match(/(?:^|;\s*)rm_attribution=([^;]*)/);
    if (m) { try { existing = JSON.parse(decodeURIComponent(m[1])); } catch (e) {} }
    Object.keys(found).forEach(function (k) { existing[k] = found[k]; });

    // Use the real domain in production, but fall back to host-only so this
    // also works on the webflow.io staging domain
    var domainAttr = location.hostname.indexOf('clearcompare.com.au') > -1
      ? '; domain=.clearcompare.com.au' : '';

    document.cookie = 'rm_attribution=' + encodeURIComponent(JSON.stringify(existing)) +
      '; max-age=' + (90 * 24 * 60 * 60) + '; path=/' + domainAttr + '; SameSite=Lax; Secure';
  } catch (e) {}
})();

window.dataLayer = window.dataLayer || [];

  window.addEventListener('message', (event) => {
    if (event.data?.type === 'RATEMATCH_TRACKING') {
      dataLayer.push({
        event: event.data.event, // 'offer_click', 'form_complete', 'offers_displayed'
        ...event.data.data
      });
    }
  });

function setupAccordion(accordionSelector, contentSelector, openFirst = false) {
  const accordions = document.querySelectorAll(accordionSelector);
  if (!accordions.length) return;

  accordions.forEach(acc => {
    const answer = acc.querySelector(contentSelector);

    acc.addEventListener("click", () => {
      const isActive = acc.classList.contains("active");

      // Close all accordions instantly (snappy close)
      accordions.forEach(a => {
        a.classList.remove("active");
        const ans = a.querySelector(contentSelector);
        ans.style.maxHeight = null;
      });

      // Open the clicked one (smooth open)
      if (!isActive) {
        acc.classList.add("active");
        answer.style.maxHeight = answer.scrollHeight + "px";
      }
    });
  });

  // Optionally open the first accordion
  if (openFirst) {
    const first = accordions[0];
    const firstAnswer = first.querySelector(contentSelector);
    first.classList.add("active");
    firstAnswer.style.maxHeight = firstAnswer.scrollHeight + "px";
  }
}

// Init both groups
setupAccordion(".faq_accordion", ".faq_answer", true);
setupAccordion(".footer_accordion", ".footer_accordion_dropdown");
